"""Fake of `worlds.make`: `make("snake")` gives the recorded seed-42 `core.World` double.

Any other world, variant or override raises `ValueError` naming it, as the real factory does
for unknown ones.
"""


def build(fx, case: str):
    rec = fx.recording(case)

    def make(world: str, variant: str = "default", **overrides: int | float):
        if (world, variant) != (rec["world"], rec["variant"]) or overrides:
            raise ValueError(
                f"the fake makes only {rec['world']}/{rec['variant']} without overrides, "
                f"not {world}/{variant} {overrides}"
            )
        return fx.double(rec["double"])

    return make
"""Fake of `methods.load_policy`: the snake rule double for any snake checkpoint.

A checkpoint whose spec differs from `spec` in observation length or action format raises
`SpecMismatchError` naming each field, as the real one does; a team the checkpoint has no
state for raises `KeyError`.
"""

from rllab.methods import SpecMismatchError


def build(fx, case: str):
    rec = fx.recording(case)

