class ReplayRandomPolicy:
    def __init__(self, fx, rec) -> None:
        self.action = fx.decode(ActionSpace, rec["action"])
        self.obs = fx.decode(Array, rec["obs"])
        self._actions = [fx.decode(Array, a) for a in rec["actions"]]
        self._next = 0

    def act(self, obs: Array, rng: np.random.Generator) -> Array:
        if self._next >= len(self._actions):
            raise LookupError(f"the double holds only {len(self._actions)} recorded actions")
        action = self._actions[self._next]
        self._next += 1
        return action.copy()


def build(fx, case: str) -> ReplayRandomPolicy:
    return ReplayRandomPolicy(fx, fx.recording(case))
